signature.code:
function registerFetcher<TData, TError = Error>(
  queryKey: QueryKey,
  options: QueryOptions<TData, TError> & { fetcher: () => Promise<TData> }
): void

examples.code:
import { registerFetcher } from 'qortex-react';

// Register a fetcher for user data
registerFetcher(
  'user-data',
  {
    fetcher: async () => {
      const response = await fetch('/api/user');
      return response.json();
    }
  }
);

// Now you can use it without specifying a fetcher
function UserProfile() {
  const { data, isLoading } = useQuery('user-data', {});

  if (isLoading) return <div>Loading...</div>;
  return <div>Hello, {data.name}!</div>;
}

import { registerFetcher } from 'qortex-react';

// Register with default options
registerFetcher(
  'products',
  {
    fetcher: async () => {
      const response = await fetch('/api/products');
      return response.json();
    },
    staleTime: 5 * 60 * 1000, // 5 minutes
    refetchOnSubscribe: 'stale'
  }
);

// Use with minimal configuration
function ProductList() {
  const { data } = useQuery('products', {});

  return (
    <div>
      {data?.map(product => (
        <div key={product.id}>{product.name}</div>
      ))}
    </div>
  );
}
